    private fun hex(s: String): ByteArray = ByteArray(s.length / 2) { s.substring(2 * it, 2 * it + 2).toInt(16).toByte() }
    private fun ByteArray.toHex(): String = joinToString("") { "%02x".format(it.toInt() and 0xFF) }

    @Test
    fun compressVectors() {
        for (v in vectors.filterIsInstance<C>()) {
            val out = OgzCodec.compress(hex(v.input), v.capacity)
            assertEquals(v.name, v.output, out?.toHex())
            if (out != null) assertArrayEquals(v.name, hex(v.input), OgzCodec.expand(out))
        }
    }

    @Test
    fun expandVectors() {
        for (v in vectors.filterIsInstance<E>()) {
            assertEquals(v.name, v.output, OgzCodec.expand(hex(v.input))?.toHex())
        }
    }

    @Test
    fun randomRoundTrip() {
        val rnd = Random(1234)
        val alphabet = "abcdefghijklmnopqrstuvwxyz ABCXYZ äöüÄÖÜß 0123456789 .,!?:-'()/@ 👍❤️🦄 éÉ\n".codePoints().toArray()
        repeat(3000) {
            val text = buildString { repeat(rnd.nextInt(60) + 1) { appendCodePoint(alphabet[rnd.nextInt(alphabet.size)]) } }
            val data = text.toByteArray(Charsets.UTF_8)
            if (data.size > OgzTables.MAX_INPUT_BYTES) return@repeat
            val enc = OgzCodec.compress(data, 255) ?: throw AssertionError("compress failed: $text")
            assertArrayEquals(text, data, OgzCodec.expand(enc))
        }
        repeat(3000) {
            val data = ByteArray(rnd.nextInt(40) + 1).also { rnd.nextBytes(it) }
            val enc = OgzCodec.compress(data, 255) ?: throw AssertionError("compress failed")
            assertArrayEquals(data, OgzCodec.expand(enc))
            OgzCodec.expand(data) // arbitrary input must not throw
        }
    }

    @Test
    fun rejectsEmptyAndOversizedInput() {
        assertNull(OgzCodec.compress(ByteArray(0)))
        assertNull(OgzCodec.compress(ByteArray(OgzTables.MAX_INPUT_BYTES + 1) { 'a'.code.toByte() }, 255))
        assertNull(OgzCodec.expand(ByteArray(0)))
    }
